import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import girl from '../pics/girl.png';
import ProductCard, { CardSkeleton } from '../components/store/ProductCard';
import { WhatsAppButton } from '../components/store/Blocks';
import Icon from '../components/store/Icon';
import useProducts from '../utils/useProducts';
import { categoryOf, logView, money } from '../utils/shop';

const BUDGETS = [
  { label: 'Under ZMW 100', test: (v) => v < 100 },
  { label: 'ZMW 100–200', test: (v) => v >= 100 && v <= 200 },
  { label: 'ZMW 200+', test: (v) => v > 200 },
];

export default function Gifting() {
  const { products, loading } = useProducts();
  const [budget, setBudget] = useState(0);

  useEffect(() => { logView('gifting', 'GiftingPage'); }, []);

  const gifts = useMemo(() => products.filter((p) => BUDGETS[budget].test(Number(p.price))).slice(0, 8), [products, budget]);
  const box = products.find((p) => categoryOf(p) === 'Gift Boxes');
  const partner = products.find((p) => p !== box && ['Necklaces', 'Earrings', 'Bracelets', 'Rings'].includes(categoryOf(p)));

  return (
    <>
      <section className="l-container l-section-sm">
        <div className="l-dark l-split">
          <div className="l-split-text">
            <p className="l-eyebrow" style={{ color: 'var(--gold-light)' }}>Gifting</p>
            <h1 className="l-h1" style={{ fontSize: 'clamp(34px, 5vw, 60px)' }}>A gift that says it for you</h1>
            <p className="l-lead" style={{ color: 'var(--line)', maxWidth: 460 }}>
              Pair a piece of jewelry with a gift box, or build your own gift from jewelry, hair accessories and flowers. Tell us who it is for and we will help you put it together.
            </p>
            <div className="l-row l-wrap l-gap-12">
              <Link to="/gift-builder" className="l-btn l-btn-light">Build a gift</Link>
              <WhatsAppButton label="Get help choosing" className="l-btn l-btn-ghost-light" text="Hi Lumina, can you help me choose a gift?" />
            </div>
          </div>
          <div className="l-split-media"><img src={box ? box.mainImage : girl} alt={box ? box.productName : 'Lumina jewelry'} /></div>
        </div>
      </section>

      <section className="l-container l-section-sm">
        <Link to="/gift-builder" className="l-dashed l-row l-wrap l-gap-16">
          <span style={{ width: 56, height: 56, borderRadius: 28, background: 'var(--sand)', color: 'var(--gold-text)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
            <Icon name="gift" size={26} stroke={1.5} />
          </span>
          <span className="l-stack" style={{ flex: '1 1 240px' }}>
            <strong className="l-serif" style={{ fontSize: 26, fontWeight: 600 }}>Build your own gift</strong>
            <span className="l-small l-muted">Mix jewelry, hair accessories and flowers, then choose a box.</span>
          </span>
          <span className="l-btn">Start building <Icon name="arrow" size={18} /></span>
        </Link>
      </section>

      <section className="l-container l-section l-stack l-gap-24">
        <div className="l-between l-wrap" style={{ alignItems: 'flex-end' }}>
          <h2 className="l-h2">Gifts by budget</h2>
          <div className="l-chips" role="tablist" aria-label="Budget">
            {BUDGETS.map((b, i) => (
              <button key={b.label} type="button" role="tab" className="l-chip" aria-selected={budget === i} onClick={() => setBudget(i)}>{b.label}</button>
            ))}
          </div>
        </div>
        <div className="l-grid">
          {loading ? Array.from({ length: 4 }).map((_, i) => <CardSkeleton key={i} />) : gifts.map((p) => <ProductCard key={p.id} product={p} />)}
        </div>
        {!loading && gifts.length === 0 && (
          <div className="l-empty"><strong className="l-h3">Nothing in this budget right now</strong><span className="l-small l-muted">Try another budget, or ask us on WhatsApp.</span></div>
        )}
      </section>

      {box && partner && (
        <section className="l-container l-section-sm">
          <div className="l-soft l-row l-wrap l-gap-24">
            <div className="l-row l-gap-12">
              <img src={box.mainImage} alt="" style={{ width: 96, height: 96, borderRadius: 16, objectFit: 'cover' }} />
              <span className="l-serif" aria-hidden="true" style={{ fontSize: 30, color: 'var(--gold-text)' }}>+</span>
              <img src={partner.mainImage} alt="" style={{ width: 96, height: 96, borderRadius: 16, objectFit: 'cover' }} />
            </div>
            <div className="l-stack l-gap-4" style={{ flex: '1 1 240px' }}>
              <span className="l-eyebrow" style={{ fontSize: 12 }}>Gift set idea</span>
              <strong className="l-serif" style={{ fontSize: 26, fontWeight: 600 }}>{box.productName} + {partner.productName}</strong>
              <span style={{ fontWeight: 500 }}>{money(Number(box.price) + Number(partner.price))}</span>
            </div>
            <Link to="/gift-builder" className="l-btn">Build this set</Link>
          </div>
        </section>
      )}

      <section className="l-container l-section l-stack l-gap-24">
        <h2 className="l-h2 l-center">How gifting works</h2>
        <div className="l-form-grid" style={{ gap: 20 }}>
          {[
            ['Choose a gift', 'Pick a piece, build your own, or ask us on WhatsApp for ideas.'],
            ['Add special packing and a note', 'Cards and rose boxes are available for an extra fee, confirmed on WhatsApp. Write your message in the cart.'],
            ['We deliver it', 'Yango biker in Lusaka, Platinum outside Lusaka.'],
          ].map(([t, d], i) => (
            <div key={t} className="l-panel l-stack l-gap-8">
              <span style={{ width: 44, height: 44, borderRadius: 22, border: '1px solid var(--gold)', color: 'var(--gold-text)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--serif)', fontSize: 22 }}>{i + 1}</span>
              <strong style={{ fontSize: 18, fontWeight: 500 }}>{t}</strong>
              <span className="l-muted" style={{ fontSize: 15 }}>{d}</span>
            </div>
          ))}
        </div>
        <Link to="/gift-builder" className="l-btn l-btn-lg" style={{ alignSelf: 'center' }}>Start building a gift</Link>
      </section>
    </>
  );
}
