import { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { getProducts } from '../store/productSlice';
import { inStock, rankProducts } from './shop';

// Loads the catalogue once per page view and returns in-stock products.
export default function useProducts() {
  const dispatch = useDispatch();
  const { products, loading, error } = useSelector((s) => s.products);

  useEffect(() => {
    dispatch(getProducts());
  }, [dispatch]);

  const available = useMemo(() => rankProducts((products || []).filter(inStock)), [products]);
  return { products: available, loading: loading && !(products || []).length, error };
}
