import { createSlice } from '@reduxjs/toolkit';

// A cart line is one product in one size:
// { id, productName, price, image, size, quantity, totalQuantity, category }
// totalQuantity is the stock left for that size.

const initialState = {
  cart: [],
  note: '',
  specialPacking: false,
};

function sameLine(a, b) {
  return a.id === b.id && String(a.size) === String(b.size);
}

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addToCart: (state, action) => {
      const item = action.payload;
      const qty = Math.max(1, Number(item.quantity) || 1);
      const existing = state.cart.find((line) => sameLine(line, item));
      if (existing) {
        existing.quantity = Math.min(existing.quantity + qty, existing.totalQuantity || Infinity);
      } else {
        state.cart.push({ ...item, quantity: Math.min(qty, item.totalQuantity || qty) });
      }
    },
    removeFromCart: (state, action) => {
      state.cart = state.cart.filter((line) => !sameLine(line, action.payload));
    },
    clearCart: (state) => {
      state.cart = [];
      state.note = '';
      state.specialPacking = false;
    },
    updateQuantity: (state, action) => {
      const line = state.cart.find((l) => sameLine(l, action.payload));
      if (line && line.quantity < (line.totalQuantity || Infinity)) line.quantity += 1;
    },
    reduceQuantity: (state, action) => {
      const line = state.cart.find((l) => sameLine(l, action.payload));
      if (line && line.quantity > 1) line.quantity -= 1;
    },
    setNote: (state, action) => {
      state.note = String(action.payload || '').slice(0, 500);
    },
    setSpecialPacking: (state, action) => {
      state.specialPacking = !!action.payload;
    },
  },
});

export const { addToCart, removeFromCart, clearCart, updateQuantity, reduceQuantity, setNote, setSpecialPacking } = cartSlice.actions;

// Older saved carts (before this update) only had { cart: [] }.
export default function cartReducer(state, action) {
  const next = cartSlice.reducer(state, action);
  if (next && (next.note === undefined || next.specialPacking === undefined)) {
    return { note: '', specialPacking: false, ...next };
  }
  return next;
}
