import { useEffect, useMemo, useState } from 'react';
import { Link, Navigate, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { clearCart, removeFromCart } from '../store/cartSlice';
import Icon from '../components/store/Icon';
import { Loader } from '../components/store/Blocks';
import { createOrder, newReference, payWithLenco, quoteCart } from '../utils/payments';
import { logView, money, totals, track, whatsappLink } from '../utils/shop';
import { DELIVERY_OPTIONS, ENABLE_CASH_ON_DELIVERY } from '../config';

const METHODS = [
  { id: 'airtel', title: 'Airtel Money', sub: 'Approve on your phone' },
  { id: 'mtn', title: 'MTN MoMo', sub: 'Approve on your phone' },
  { id: 'card', title: 'Debit or credit card', sub: 'Visa, Mastercard' },
  ...(ENABLE_CASH_ON_DELIVERY ? [{ id: 'cash', title: 'Cash on delivery', sub: 'Pay when it arrives' }] : []),
];

export default function Checkout() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { cart, note, specialPacking } = useSelector((s) => s.cart);
  const local = totals(cart);

  const [quote, setQuote] = useState(null);
  const [quoteError, setQuoteError] = useState('');
  const [phone, setPhone] = useState('');
  const [delivery, setDelivery] = useState('lusaka');
  const [method, setMethod] = useState('airtel');
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState('');
  const [message, setMessage] = useState('');

  useEffect(() => { logView('payment', 'PaymemtPage'); }, []);

  const cartKey = useMemo(() => cart.map((i) => `${i.id}:${i.size}:${i.quantity}`).join('|'), [cart]);
  useEffect(() => {
    if (!cart.length) return;
    let cancelled = false;
    setQuoteError('');
    quoteCart(cart).then(({ ok, data }) => {
      if (cancelled) return;
      if (ok) setQuote(data);
      else setQuoteError(data.message || 'We could not check your cart right now.');
    }).catch(() => !cancelled && setQuoteError('We could not reach the shop. Check your connection and try again.'));
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cartKey]);

  if (!cart.length && !busy) return <Navigate to="/cart" replace />;

  const sum = quote || local;
  const problems = quote?.problems || [];

  function check() {
    const e = {};
    if (!/^0[79]\d{8}$/.test(phone.replace(/\s+/g, ''))) e.phone = 'Use 10 digits, like 0977123456.';
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  function orderPayload(reference) {
    return {
      reference,
      paymentMethod: method,
      customer: { phone: phone.replace(/\s+/g, '') },
      delivery: { method: delivery },
      note,
      specialPacking,
      cart: cart.map(({ id, size, quantity }) => ({ id, size, quantity })),
    };
  }

  function finish(order) {
    track('Purchase', { value: order.total, currency: 'ZMW', content_ids: order.items.map((i) => i.id), content_type: 'product' });
    dispatch(clearCart());
    navigate('/order-confirmed', { replace: true, state: { order } });
  }

  async function submit(e) {
    e.preventDefault();
    setMessage('');
    if (!check()) return;
    if (!quote) { setMessage(quoteError || 'Still checking your cart. One moment…'); return; }
    if (problems.length) { setMessage('Some items in your cart have sold out. Please update your cart.'); return; }

    track('InitiateCheckout', { value: quote.total, currency: 'ZMW', content_ids: cart.map((i) => i.id), content_type: 'product' });

    try {
      if (method === 'cash') {
        setBusy('Placing your order…');
        const { ok, data } = await createOrder(orderPayload(null));
        if (!ok) throw new Error(data.message || 'We could not place your order.');
        finish(data.order);
        return;
      }

      if (!quote.receiptEmail) throw new Error('Online payment is not set up yet. Please order on WhatsApp for now.');
      setBusy('Opening secure payment…');
      const reference = newReference();
      const result = await payWithLenco({ amount: quote.total, email: quote.receiptEmail, phone: phone.replace(/\s+/g, ''), method, reference });
      if (result.outcome === 'closed') {
        setBusy('');
        setMessage('Payment was not completed. You have not been charged. You can try again.');
        return;
      }
      setBusy('Confirming your payment…');
      const { ok, data } = await createOrder(orderPayload(result.reference));
      if (!ok) throw new Error(data.message || 'We could not confirm your payment.');
      finish(data.order);
    } catch (err) {
      setBusy('');
      setMessage(err.message || 'Something went wrong. Please try again.');
    }
  }

  const ctaLabel = method === 'cash' ? 'Place order' : `Pay ${money(sum.total)}`;

  return (
    <form className="l-container l-section l-stack l-gap-24 l-has-mobile-bar" onSubmit={submit} noValidate>
      <div className="l-between l-wrap">
        <h1 className="l-h2">Checkout</h1>
        <span className="l-row l-gap-8 l-small l-muted"><Icon name="lock" size={18} /> Secure payment by Lenco</span>
      </div>
      <ol className="l-steps" aria-label="Checkout steps">
        <li className="is-done"><Link to="/cart">Cart</Link></li>
        <li aria-current="step">Details &amp; payment</li>
        <li>Confirmation</li>
      </ol>

      <div className="l-row l-wrap" style={{ alignItems: 'flex-start', gap: 40 }}>
        <div className="l-stack" style={{ flex: '999 1 540px', minWidth: 0, gap: 36 }}>
          <section className="l-stack l-gap-16">
            <h2 className="l-h3" style={{ fontSize: 30, fontWeight: 500 }}>1. Your phone number</h2>
            <div className="l-form-grid">
              <Field label="Phone (WhatsApp)" error={errors.phone}><input className={`l-input${errors.phone ? ' is-error' : ''}`} type="tel" inputMode="numeric" autoComplete="tel" value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="0977123456" /></Field>
            </div>
            <p className="l-small l-muted" style={{ margin: 0 }}>We will message you on this number to confirm your order and get your delivery address.</p>
          </section>

          <section className="l-stack l-gap-16">
            <h2 className="l-h3" style={{ fontSize: 30, fontWeight: 500 }}>2. Delivery</h2>
            <div className="l-option-grid" role="radiogroup" aria-label="Delivery">
              {DELIVERY_OPTIONS.map((d) => (
                <button key={d.id} type="button" role="radio" aria-checked={delivery === d.id} className="l-option" onClick={() => setDelivery(d.id)}>
                  <span className="l-radio" />
                  <span className="l-stack" style={{ flex: 1 }}><span style={{ fontWeight: 500 }}>{d.label}</span><span className="l-xsmall l-muted">{d.note}</span></span>
                </button>
              ))}
            </div>
            <p className="l-small l-muted" style={{ margin: 0 }}>We confirm your address, the delivery fee and the time with you on WhatsApp after you order.</p>
          </section>

          <section className="l-stack l-gap-16">
            <h2 className="l-h3" style={{ fontSize: 30, fontWeight: 500 }}>3. Payment</h2>
            <div className="l-option-grid" role="radiogroup" aria-label="Payment method">
              {METHODS.map((m) => (
                <button key={m.id} type="button" role="radio" aria-checked={method === m.id} className="l-option" onClick={() => setMethod(m.id)}>
                  <span className="l-radio" />
                  <span className="l-stack" style={{ flex: 1 }}><span style={{ fontWeight: 500 }}>{m.title}</span><span className="l-xsmall l-muted">{m.sub}</span></span>
                </button>
              ))}
            </div>
            <div className="l-soft l-small" style={{ padding: '16px 18px', borderRadius: 16 }}>
              {method === 'cash'
                ? 'Pay in cash when your order arrives. We will confirm your order on WhatsApp.'
                : method === 'card'
                  ? 'A secure Lenco window opens for your card details. Lumina never sees your card number.'
                  : `A secure Lenco window opens. Choose ${method === 'mtn' ? 'MTN' : 'Airtel'}, enter your number, then approve the prompt on your phone with your PIN.`}
            </div>
          </section>
        </div>

        <aside className="l-panel l-stack l-gap-12" style={{ flex: '1 1 340px', minWidth: 0 }}>
          <h2 className="l-h3" style={{ fontSize: 30, fontWeight: 500 }}>Your order</h2>
          {!quote && !quoteError && <Loader />}
          {quoteError && <p className="l-error" role="alert">{quoteError}</p>}
          {(quote ? quote.items : cart).map((i) => {
            const p = problems.find((x) => x.id === i.id && String(x.size) === String(i.size));
            return (
              <div key={`${i.id}-${i.size}`} className="l-row l-gap-12">
                <img src={i.image} alt="" style={{ width: 56, height: 56, borderRadius: 12, objectFit: 'cover', flexShrink: 0 }} />
                <div className="l-stack" style={{ flex: 1, minWidth: 0 }}>
                  <span style={{ fontWeight: 500 }}>{i.productName}</span>
                  <span className="l-xsmall l-muted">Size {i.size} · Qty {i.quantity}</span>
                  {p && <span className="l-error">{p.message} <button type="button" style={{ border: 0, background: 'none', textDecoration: 'underline', padding: 0, color: 'inherit' }} onClick={() => dispatch(removeFromCart(i))}>Remove</button></span>}
                </div>
                <span className="l-small">{money(i.price * i.quantity)}</span>
              </div>
            );
          })}
          <div className="l-divider" />
          <div className="l-line-row"><span>Subtotal</span><span>{money(sum.subtotal)}</span></div>
          <div className="l-line-row"><span>Discount</span><span>{sum.discount ? `− ${money(sum.discount)}` : '—'}</span></div>
          <div className="l-line-row"><span>Delivery</span><span>Confirmed on WhatsApp</span></div>
          {specialPacking && <div className="l-line-row"><span>Special packing</span><span>Fee confirmed on WhatsApp</span></div>}
          <div className="l-total-row"><span>Total</span><span>{money(sum.total)}</span></div>
          {message && <p className="l-error" role="alert" style={{ margin: 0 }}>{message}</p>}
          <button type="submit" className="l-btn l-btn-lg l-btn-block l-hide-phone" disabled={!!busy || !quote}>{busy || ctaLabel}</button>
          <a className="l-btn l-btn-outline l-btn-block" href={whatsappLink(`Hi Lumina, I need help with my order (total ${money(sum.total)}).`)} target="_blank" rel="noreferrer"><Icon name="whatsapp" size={18} />Need help? WhatsApp us</a>
        </aside>
      </div>

      <div className="l-mobile-bar">
        <div className="l-stack" style={{ flex: 1, minWidth: 0 }}>
          <span className="l-xsmall l-muted">{local.items} {local.items === 1 ? 'item' : 'items'} · delivery on WhatsApp</span>
          <span style={{ fontSize: 18, fontWeight: 500 }}>Total {money(sum.total)}</span>
        </div>
        <button type="submit" className="l-btn l-btn-lg" disabled={!!busy || !quote}>{busy ? 'Please wait…' : ctaLabel}</button>
      </div>
    </form>
  );
}

function Field({ label, error, children }) {
  return (
    <label className="l-field">
      {label}
      {children}
      {error && <span className="l-error">{error}</span>}
    </label>
  );
}
