import { CATEGORIES, NAME_RULES, SHOW_FIRST, CURRENCY, DISCOUNT_RATE, DISCOUNT_THRESHOLD, WHATSAPP_NUMBER } from '../config';

export function money(value) {
  const n = Number(value) || 0;
  const rounded = Math.round(n * 100) / 100;
  return `${CURRENCY} ${rounded.toLocaleString('en-US', { maximumFractionDigits: 2 })}`;
}

export function parseSizes(product) {
  if (!product || !product.sizes) return [];
  if (Array.isArray(product.sizes)) return product.sizes;
  try {
    const parsed = JSON.parse(product.sizes);
    return Array.isArray(parsed) ? parsed.map((s) => ({ size: String(s.size), quantity: Number(s.quantity) || 0 })) : [];
  } catch (e) {
    return [];
  }
}

export function inStock(product) {
  return Number(product?.quantity) > 0;
}

// Map a product's free-text category onto one of the shop categories.
export function categoryOf(product) {
  const raw = String(product?.category || '').trim().toLowerCase();
  // 1. The product name wins: anything called "... Stand" is a stand, even
  //    if it was uploaded under "Jewelry Boxes".
  const name = String(product?.productName || '').toLowerCase();
  const rule = NAME_RULES.find((r) => r.words.some((w) => name.includes(w)));
  if (rule) return rule.category;
  // 2. Otherwise the category, typed exactly or with a close spelling.
  const found = CATEGORIES.find((c) => c.name.toLowerCase() === raw || c.match.includes(raw));
  return found ? found.name : product?.category || 'Other';
}

// Upload time in milliseconds (Firestore dates arrive in a few shapes).
export function createdMs(product) {
  const c = product?.createdAt;
  if (!c) return 0;
  if (typeof c === 'number') return c;
  if (typeof c === 'string') return Date.parse(c) || 0;
  const secs = c._seconds ?? c.seconds;
  return secs ? secs * 1000 : 0;
}

// Sorts by the SHOW_FIRST category order, newest first inside each category.
export function rankProducts(list) {
  const rank = (p) => {
    const i = SHOW_FIRST.indexOf(categoryOf(p));
    return i === -1 ? SHOW_FIRST.length : i;
  };
  return [...list].sort((a, b) => rank(a) - rank(b) || createdMs(b) - createdMs(a));
}

export function newestIds(list, n = 2) {
  return new Set([...list].sort((a, b) => createdMs(b) - createdMs(a)).slice(0, n).map((p) => p.id));
}

export function categoryMark(name) {
  const c = CATEGORIES.find((x) => x.name === name);
  return (c && c.mark) || name.charAt(0);
}

export function totals(cart) {
  const subtotal = cart.reduce((sum, item) => sum + Number(item.price) * item.quantity, 0);
  const discount = subtotal > DISCOUNT_THRESHOLD ? Math.round(subtotal * DISCOUNT_RATE * 100) / 100 : 0;
  const items = cart.reduce((sum, item) => sum + item.quantity, 0);
  return { subtotal, discount, total: Math.round((subtotal - discount) * 100) / 100, items };
}

export function whatsappLink(text) {
  const base = `https://wa.me/${WHATSAPP_NUMBER}`;
  return text ? `${base}?text=${encodeURIComponent(text)}` : base;
}

export function cartWhatsappMessage(cart, extra) {
  const { subtotal, discount, total } = totals(cart);
  const lines = cart.map((i) => `• ${i.productName} (size ${i.size}) × ${i.quantity} = ${money(i.price * i.quantity)}`);
  let msg = `Hi Lumina, I'd like to order:\n${lines.join('\n')}\nSubtotal: ${money(subtotal)}`;
  if (discount) msg += `\nDiscount: -${money(discount)}`;
  msg += `\nTotal: ${money(total)}`;
  if (extra) msg += `\n${extra}`;
  return msg;
}

const API = '/api';

export async function logView(name, view) {
  try {
    await fetch(`${API}/views`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name, view }),
    });
  } catch (e) {
    // analytics must never break the page
  }
}

export function track(event, data) {
  if (window.fbq) window.fbq('track', event, data);
}
