import { useEffect, useMemo, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import ProductCard, { CardSkeleton } from '../components/store/ProductCard';
import { WhatsAppButton } from '../components/store/Blocks';
import Icon from '../components/store/Icon';
import useProducts from '../utils/useProducts';
import { categoryOf, createdMs, logView } from '../utils/shop';
import { CATEGORIES } from '../config';

const SORTS = ['Featured', 'Newest', 'Price: low to high', 'Price: high to low'];

export default function Shop() {
  const { products, loading } = useProducts();
  const [params, setParams] = useSearchParams();
  const category = params.get('category') || 'All';
  const q = params.get('q') || '';
  const sort = Number(params.get('sort') || 0);
  const searchRef = useRef(null);

  useEffect(() => { logView('shop', 'ShopPage'); }, []);
  useEffect(() => {
    if (params.get('search') && searchRef.current) searchRef.current.focus();
  }, [params]);

  function update(next) {
    const p = new URLSearchParams(params);
    p.delete('search');
    Object.entries(next).forEach(([k, v]) => (v === null || v === '' || v === 'All' || v === 0 ? p.delete(k) : p.set(k, v)));
    setParams(p, { replace: true });
  }

  const list = useMemo(() => {
    let l = products;
    if (category !== 'All') l = l.filter((p) => categoryOf(p) === category);
    if (q) {
      const t = q.toLowerCase();
      l = l.filter((p) => `${p.productName} ${p.category} ${p.description || ''}`.toLowerCase().includes(t));
    }
    if (sort === 1) l = [...l].sort((a, b) => createdMs(b) - createdMs(a));
    if (sort === 2) l = [...l].sort((a, b) => a.price - b.price);
    if (sort === 3) l = [...l].sort((a, b) => b.price - a.price);
    return l;
  }, [products, category, q, sort]);

  const heading = category === 'All' ? (q ? `Results for “${q}”` : 'Shop all') : category;

  return (
    <div className="l-container l-section l-stack l-gap-24">
      <div className="l-between l-wrap" style={{ alignItems: 'flex-end' }}>
        <h1 className="l-h2">{heading}</h1>
        <span className="l-small l-muted">{loading ? 'Loading…' : `${list.length} ${list.length === 1 ? 'product' : 'products'}`}</span>
      </div>

      <form className="l-row l-gap-8" role="search" onSubmit={(e) => { e.preventDefault(); update({ q: searchRef.current.value.trim() }); }}>
        <label className="l-sr" htmlFor="shop-search">Search products</label>
        <input id="shop-search" ref={searchRef} className="l-input" defaultValue={q} key={q} placeholder="Search rings, necklaces, gift boxes…" style={{ borderRadius: 999, maxWidth: 520 }} />
        <button type="submit" className="l-btn" aria-label="Search"><Icon name="search" size={18} /></button>
      </form>

      <div className="l-chips" role="tablist" aria-label="Category">
        {['All', ...CATEGORIES.map((c) => c.name)].map((c) => (
          <button key={c} type="button" role="tab" className="l-chip" aria-selected={category === c} onClick={() => update({ category: c })}>{c}</button>
        ))}
      </div>

      <div className="l-between l-divider" style={{ borderBottom: '1px solid var(--line)', minHeight: 52 }}>
        <span className="l-small l-muted">Sort by</span>
        <button type="button" className="l-row l-gap-8" style={{ border: 0, background: 'transparent', minHeight: 44, fontWeight: 500 }} onClick={() => update({ sort: (sort + 1) % SORTS.length })}>
          {SORTS[sort]} <Icon name="sort" size={16} />
        </button>
      </div>

      <div className="l-grid">
        {loading ? Array.from({ length: 6 }).map((_, i) => <CardSkeleton key={i} />) : list.map((p) => <ProductCard key={p.id} product={p} />)}
      </div>

      {!loading && list.length === 0 && (
        <div className="l-empty">
          <strong className="l-h3">{category === 'All' ? 'No matching products' : `No ${category.toLowerCase()} listed yet`}</strong>
          <span className="l-small l-muted">New pieces arrive often. Ask us on WhatsApp what is in stock right now.</span>
          <WhatsAppButton label="Ask on WhatsApp" className="l-btn" text={`Hi Lumina, do you have any ${category === 'All' ? q : category.toLowerCase()} in stock?`} />
        </div>
      )}
    </div>
  );
}
