import './App.css';
import './theme.css';
import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';

import StoreLayout from './layout/StoreLayout';
import AdminLayout from './layout/DashbaordLayout';
import Home from './pages/Home';
import Shop from './pages/Shop';
import Product from './pages/Product';
import Cart from './pages/Cart';
import Checkout from './pages/Checkout';
import OrderConfirmed from './pages/OrderConfirmed';
import Gifting from './pages/Gifting';
import GiftBuilder from './pages/GiftBuilder';
import Faq from './pages/Faq';
import UploadItem from './pages/UploadItem';
import ViewStats from './pages/ViewStats';

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route element={<StoreLayout />}>
          <Route path="/" element={<Home />} />
          <Route path="/shop" element={<Shop />} />
          <Route path="/product/:id" element={<Product />} />
          <Route path="/cart" element={<Cart />} />
          <Route path="/checkout" element={<Checkout />} />
          <Route path="/order-confirmed" element={<OrderConfirmed />} />
          <Route path="/gifting" element={<Gifting />} />
          <Route path="/gift-builder" element={<GiftBuilder />} />
          <Route path="/faq" element={<Faq />} />
          {/* Old addresses, kept so existing links still work */}
          <Route path="/payment" element={<Navigate to="/checkout" replace />} />
          <Route path="/chat" element={<Navigate to="/faq" replace />} />
          <Route path="/receipt" element={<Navigate to="/order-confirmed" replace />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Route>
        <Route element={<AdminLayout />}>
          <Route path="/upload" element={<UploadItem />} />
          <Route path="/viewStats" element={<ViewStats />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}

export default App;
