import { useRef, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';
import Icon from '../components/store/Icon';
import { WhatsAppButton } from '../components/store/Blocks';
import { money } from '../utils/shop';

const METHOD_NAMES = { airtel: 'Airtel Money', mtn: 'MTN MoMo', card: 'Card', cash: 'Cash on delivery' };

const STATUS_TEXT = {
  paid: 'Payment received. We will message you on WhatsApp with delivery details.',
  'paid-unverified': 'Thank you. We will check your payment and message you on WhatsApp with delivery details.',
  'paid-needs-attention': 'Payment received. One of your items just sold out, so we will message you on WhatsApp to sort it out.',
  'paid-wrong-amount': 'Thank you. We will check your payment amount and message you on WhatsApp.',
  'payment-pending': 'Your payment is still being confirmed. We will message you on WhatsApp as soon as it clears.',
  'payment-check-failed': 'We received your order. We will confirm your payment and message you on WhatsApp.',
  'awaiting-cash': 'Your order is placed. Pay in cash when it arrives. We will confirm delivery on WhatsApp.',
};

export default function OrderConfirmed() {
  const { state } = useLocation();
  const order = state?.order;
  const receiptRef = useRef(null);
  const [saving, setSaving] = useState(false);

  if (!order) {
    return (
      <div className="l-container l-section">
        <div className="l-empty">
          <strong className="l-h3">No recent order to show</strong>
          <span className="l-small l-muted">If you just paid and don't see a confirmation, message us on WhatsApp with your payment reference.</span>
          <div className="l-row l-wrap l-gap-12" style={{ justifyContent: 'center' }}>
            <Link to="/" className="l-btn">Back to the shop</Link>
            <WhatsAppButton />
          </div>
        </div>
      </div>
    );
  }

  async function downloadReceipt() {
    setSaving(true);
    try {
      const canvas = await html2canvas(receiptRef.current, { scale: 2, useCORS: true, backgroundColor: '#FFFFFF' });
      const pdf = new jsPDF('p', 'mm', 'a4');
      const w = pdf.internal.pageSize.getWidth();
      pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, 0, w, (canvas.height * w) / canvas.width);
      pdf.save(`Lumina-receipt-${order.orderNumber}.pdf`);
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="l-container l-section l-stack l-gap-16" style={{ maxWidth: 680, alignItems: 'center', textAlign: 'center' }}>
      <span style={{ width: 84, height: 84, borderRadius: 42, background: 'var(--ink)', color: 'var(--cream)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <Icon name="check" size={38} stroke={2} />
      </span>
      <p className="l-eyebrow">Order {order.orderNumber}</p>
      <h1 className="l-h1" style={{ fontSize: 'clamp(34px, 5vw, 56px)' }}>Thank you for your order</h1>
      <p className="l-lead" style={{ maxWidth: 500 }}>{STATUS_TEXT[order.status] || STATUS_TEXT.paid}</p>

      <div ref={receiptRef} className="l-panel l-stack l-gap-12" style={{ width: '100%', textAlign: 'left', marginTop: 8 }}>
        <div className="l-between"><strong className="l-serif" style={{ fontSize: 26 }}>Lumina receipt</strong><span className="l-small l-muted">{new Date().toLocaleDateString()}</span></div>
        {order.items.map((i) => (
          <div key={`${i.id}-${i.size}`} className="l-row l-gap-12">
            <div className="l-stack" style={{ flex: 1 }}>
              <span style={{ fontWeight: 500 }}>{i.productName}</span>
              <span className="l-xsmall l-muted">Size {i.size} · Qty {i.quantity}</span>
            </div>
            <span>{money(i.lineTotal ?? i.price * i.quantity)}</span>
          </div>
        ))}
        <div className="l-divider" />
        <div className="l-line-row"><span>Subtotal</span><span>{money(order.subtotal)}</span></div>
        <div className="l-line-row"><span>Discount</span><span>{order.discount ? `− ${money(order.discount)}` : '—'}</span></div>
        <div className="l-line-row"><span>Payment</span><span>{METHOD_NAMES[order.paymentMethod]}</span></div>
        {order.reference && <div className="l-line-row"><span>Reference</span><span style={{ wordBreak: 'break-all' }}>{order.reference}</span></div>}
        <div className="l-line-row"><span>Delivery</span><span>{order.delivery?.method === 'outside' ? 'Platinum, outside Lusaka' : 'Yango biker, Lusaka'}</span></div>
        <div className="l-total-row"><span>{order.paymentMethod === 'cash' ? 'To pay on delivery' : 'Total'}</span><span>{money(order.total)}</span></div>
      </div>

      <div className="l-row l-wrap l-gap-12" style={{ justifyContent: 'center', marginTop: 8 }}>
        <button type="button" className="l-btn l-btn-outline" onClick={downloadReceipt} disabled={saving}>{saving ? 'Preparing…' : 'Download receipt'}</button>
        <WhatsAppButton label="Message us on WhatsApp" text={`Hi Lumina, I just placed order ${order.orderNumber}${order.reference ? ` (payment ref ${order.reference})` : ''}.`} />
        <Link to="/" className="l-btn">Continue shopping</Link>
      </div>
    </div>
  );
}
