import { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { addToCart, setNote, setSpecialPacking } from '../store/cartSlice';
import Icon from '../components/store/Icon';
import { Loader, WhatsAppButton } from '../components/store/Blocks';
import { useToast } from '../components/store/Toast';
import useProducts from '../utils/useProducts';
import { categoryOf, logView, money, parseSizes, track } from '../utils/shop';
import { GIFT_SECTIONS } from '../config';

const ICONS = { jewelry: 'jewelry', hair: 'hair', flowers: 'flowers', box: 'box' };

export default function GiftBuilder() {
  const { products, loading } = useProducts();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const toast = useToast();
  const cartState = useSelector((s) => s.cart);

  const [tab, setTab] = useState(GIFT_SECTIONS[0].id);
  const [picked, setPicked] = useState({}); // productId -> size
  const [packing, setPacking] = useState(cartState.specialPacking);
  const [note, setNoteText] = useState(cartState.note);

  useEffect(() => { logView('gift-builder', 'GiftBuilderPage'); }, []);

  const bySection = useMemo(() => {
    const map = {};
    GIFT_SECTIONS.forEach((s) => {
      map[s.id] = products.filter((p) => s.categories.includes(categoryOf(p)));
    });
    return map;
  }, [products]);

  const section = GIFT_SECTIONS.find((s) => s.id === tab);
  const items = bySection[tab] || [];
  const chosen = products.filter((p) => picked[p.id] !== undefined);
  const total = chosen.reduce((sum, p) => sum + Number(p.price), 0);

  function sizesOf(p) { return parseSizes(p).filter((s) => s.quantity > 0); }

  function toggle(p) {
    const next = { ...picked };
    if (next[p.id] !== undefined) {
      delete next[p.id];
    } else {
      if (section.pickOne) items.forEach((x) => delete next[x.id]);
      const s = sizesOf(p);
      next[p.id] = s.length ? s[0].size : '';
    }
    setPicked(next);
  }

  function addGift() {
    if (!chosen.length) return;
    chosen.forEach((p) => {
      const s = sizesOf(p).find((x) => x.size === picked[p.id]) || sizesOf(p)[0];
      dispatch(addToCart({
        id: p.id, productName: p.productName, price: Number(p.price), image: p.mainImage,
        size: s ? s.size : 'One size', quantity: 1, totalQuantity: s ? s.quantity : 1, category: p.category,
      }));
    });
    dispatch(setSpecialPacking(packing));
    dispatch(setNote(note));
    track('AddToCart', { content_ids: chosen.map((p) => p.id), content_type: 'product', value: total, currency: 'ZMW' });
    toast('Your gift was added to the cart');
    navigate('/cart');
  }

  const counts = (id) => (bySection[id] || []).filter((p) => picked[p.id] !== undefined).length;

  const summary = (
    <>
      <div className="l-stack l-gap-8">
        {chosen.length === 0 && <p className="l-muted" style={{ margin: 0 }}>Nothing picked yet. Add items from the sections.</p>}
        {chosen.map((p) => (
          <div key={p.id} className="l-row l-gap-12" style={{ minHeight: 44 }}>
            <img src={p.mainImage} alt="" style={{ width: 44, height: 44, borderRadius: 10, objectFit: 'cover' }} />
            <span style={{ flex: 1, minWidth: 0 }}>{p.productName}{picked[p.id] && sizesOf(p).length > 1 ? ` · ${picked[p.id]}` : ''}</span>
            <span className="l-small l-muted">{money(p.price)}</span>
            <button type="button" className="l-icon-btn" aria-label={`Remove ${p.productName}`} onClick={() => { const n = { ...picked }; delete n[p.id]; setPicked(n); }}>×</button>
          </div>
        ))}
      </div>
      <div className="l-divider" />
      <button type="button" role="switch" aria-checked={packing} onClick={() => setPacking(!packing)} className="l-row l-gap-12" style={{ border: 0, background: 'transparent', textAlign: 'left', minHeight: 52, padding: 0 }}>
        <span className="l-stack" style={{ flex: 1 }}>
          <span style={{ fontWeight: 500 }}>Special packing</span>
          <span className="l-small l-muted">Card or rose box. Extra fee confirmed on WhatsApp.</span>
        </span>
        <span className="l-switch" />
      </button>
      <label className="l-field">Gift note (optional)
        <textarea className="l-input" style={{ minHeight: 72 }} placeholder="Happy birthday, with love…" value={note} onChange={(e) => setNoteText(e.target.value)} maxLength={500} />
      </label>
      <div className="l-total-row"><span>Total</span><span>{money(total)}</span></div>
      <button type="button" className="l-btn l-btn-lg l-btn-block" disabled={!chosen.length} onClick={addGift}>Add gift to cart</button>
      <WhatsAppButton label="Need ideas? Ask on WhatsApp" className="l-btn l-btn-outline l-btn-block" text="Hi Lumina, can you help me build a gift?" />
    </>
  );

  return (
    <>
      <div className="l-container l-breadcrumb l-hide-phone"><Link to="/gifting">Gifting</Link> / <span style={{ color: 'var(--ink)' }}>Build a gift</span></div>
      <div className="l-container l-section-sm l-has-mobile-bar">
        <div className="l-row l-wrap" style={{ alignItems: 'flex-start', gap: 40 }}>
          <div className="l-stack l-gap-24" style={{ flex: '999 1 560px', minWidth: 0 }}>
            <div className="l-stack l-gap-8">
              <h1 className="l-h1" style={{ fontSize: 'clamp(32px, 4.5vw, 52px)' }}>Build a gift</h1>
              <p className="l-lead" style={{ fontSize: 16 }}>Pick a few things they will love, choose a box, and we will put it together.</p>
            </div>

            <div className="l-gtabs" role="tablist" aria-label="Gift sections">
              {GIFT_SECTIONS.map((s) => (
                <button key={s.id} type="button" role="tab" className="l-gtab" aria-selected={tab === s.id} onClick={() => setTab(s.id)}>
                  <Icon name={ICONS[s.id]} size={24} stroke={1.5} />
                  {s.label}
                  {counts(s.id) > 0 && <span className="l-badge">{counts(s.id)}</span>}
                </button>
              ))}
            </div>

            <div className="l-between">
              <h2 className="l-h3" style={{ fontSize: 28, fontWeight: 500 }}>{section.title}</h2>
              <span className="l-small l-muted">{section.pickOne ? 'Pick one' : 'Pick any'}</span>
            </div>

            {loading ? <Loader /> : items.length === 0 ? (
              <div className="l-empty">
                <strong className="l-h3">No {section.title.toLowerCase()} listed yet</strong>
                <span className="l-small l-muted">Ask us on WhatsApp what we can add to your gift.</span>
                <WhatsAppButton label="Ask on WhatsApp" className="l-btn" text={`Hi Lumina, what ${section.title.toLowerCase()} can I add to a gift?`} />
              </div>
            ) : (
              <div className="l-ggrid">
                {items.map((p) => {
                  const on = picked[p.id] !== undefined;
                  const s = sizesOf(p);
                  return (
                    <div key={p.id} className={`l-gcard${on ? ' is-on' : ''}`}>
                      <img src={p.mainImage} alt={p.productName} loading="lazy" />
                      <span style={{ fontSize: 15, fontWeight: 500, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{p.productName}</span>
                      {on && s.length > 1 && (
                        <label className="l-xsmall l-muted">Size{' '}
                          <select value={picked[p.id]} onChange={(e) => setPicked({ ...picked, [p.id]: e.target.value })}>
                            {s.map((x) => <option key={x.size} value={x.size}>{x.size}</option>)}
                          </select>
                        </label>
                      )}
                      <div className="l-card-row">
                        <span className="l-small l-muted">{money(p.price)}</span>
                        <button type="button" className={`l-btn l-btn-sm${on ? '' : ' l-btn-outline'}`} aria-pressed={on} onClick={() => toggle(p)}>
                          {section.pickOne ? (on ? 'Chosen ✓' : 'Choose') : (on ? 'Added ✓' : 'Add +')}
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}

            <div className="l-phone-only l-stack l-gap-12" style={{ flexDirection: 'column' }}>{summary}</div>
          </div>

          <aside className="l-panel l-stack l-gap-16 l-hide-phone" style={{ flex: '1 1 340px', minWidth: 0, position: 'sticky', top: 100 }}>
            <h2 className="l-h3" style={{ fontSize: 30, fontWeight: 500 }}>Your gift</h2>
            {summary}
          </aside>
        </div>
      </div>

      <div className="l-mobile-bar">
        <div className="l-stack" style={{ flex: 1, minWidth: 0 }}>
          <span className="l-xsmall l-muted">Your gift · {chosen.length} {chosen.length === 1 ? 'item' : 'items'}{packing ? ' + packing' : ''}</span>
          <span style={{ fontSize: 17, fontWeight: 500 }}>{money(total)}</span>
        </div>
        <button type="button" className="l-btn" disabled={!chosen.length} onClick={addGift}>Add gift to cart</button>
      </div>
    </>
  );
}
