import { useState } from 'react';
import { FAQS } from '../../config';
import { whatsappLink } from '../../utils/shop';
import Icon from './Icon';

export function FaqList({ items = FAQS, initialOpen = -1 }) {
  const [open, setOpen] = useState(initialOpen);
  return (
    <div className="l-faq">
      {items.map((f, i) => {
        const isOpen = open === i;
        return (
          <div className="l-faq-item" key={f.q}>
            <button type="button" className="l-faq-q" aria-expanded={isOpen} aria-controls={`faq-${i}`} onClick={() => setOpen(isOpen ? -1 : i)}>
              {f.q}
              <span className="l-faq-sign" aria-hidden="true">{isOpen ? '−' : '+'}</span>
            </button>
            {isOpen && <p className="l-faq-a" id={`faq-${i}`}>{f.a}</p>}
          </div>
        );
      })}
    </div>
  );
}

export function TrustStrip() {
  const items = [
    { icon: 'whatsapp', title: 'Order on WhatsApp', text: 'Ask questions and order with a real person.' },
    { icon: 'truck', title: 'Delivery', text: 'Yango biker in Lusaka, Platinum outside Lusaka.' },
    { icon: 'gift', title: 'Special packing', text: 'Cards and rose boxes on request, for an extra fee.' },
    { icon: 'shield', title: 'Secure checkout', text: 'Airtel Money, MTN MoMo or card, through Lenco.' },
  ];
  return (
    <section className="l-trust l-section-sm" style={{ marginTop: 64 }}>
      <div className="l-container l-trust-grid">
        {items.map((i) => (
          <div className="l-trust-item" key={i.title}>
            <Icon name={i.icon} size={30} stroke={1.4} />
            <div className="l-stack l-gap-4">
              <strong style={{ fontWeight: 500 }}>{i.title}</strong>
              <span className="l-small l-muted">{i.text}</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

export function Loader() {
  return <div className="l-loader"><div className="l-spinner" role="status" aria-label="Loading" /></div>;
}

export function WhatsAppButton({ text, label = 'Chat on WhatsApp', className = 'l-btn l-btn-outline' }) {
  return (
    <a className={className} href={whatsappLink(text)} target="_blank" rel="noreferrer">
      <Icon name="whatsapp" size={18} />{label}
    </a>
  );
}
