import { useEffect, useMemo, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { getProductById } from '../store/productSlice';
import { addToCart } from '../store/cartSlice';
import ProductCard from '../components/store/ProductCard';
import { Loader, WhatsAppButton } from '../components/store/Blocks';
import { useToast } from '../components/store/Toast';
import Icon from '../components/store/Icon';
import useProducts from '../utils/useProducts';
import { categoryOf, logView, money, parseSizes, track, whatsappLink } from '../utils/shop';

export default function Product() {
  const { id } = useParams();
  const dispatch = useDispatch();
  const toast = useToast();
  const { product: loaded, loading, error } = useSelector((s) => s.products);
  const { products } = useProducts();
  const product = loaded && loaded.id === id ? loaded : null;

  const [image, setImage] = useState(null);
  const [size, setSize] = useState(null);
  const [qty, setQty] = useState(1);
  const [added, setAdded] = useState(false);

  useEffect(() => { dispatch(getProductById(id)); }, [dispatch, id]);

  const sizes = useMemo(() => parseSizes(product), [product]);
  const images = useMemo(() => {
    if (!product) return [];
    const list = [product.mainImage, ...(product.subImages || [])].filter(Boolean);
    return Array.from(new Set(list));
  }, [product]);

  useEffect(() => {
    if (!product) return;
    setImage(images[0] || null);
    const inStockSizes = sizes.filter((s) => s.quantity > 0);
    setSize(inStockSizes.length === 1 ? inStockSizes[0].size : null);
    setQty(1);
    setAdded(false);
    logView(product.productName, 'ProductPage');
    track('ViewContent', { content_ids: [product.id], content_name: product.productName, content_type: 'product', value: product.price, currency: 'ZMW' });
  }, [product, images, sizes]);

  const chosen = sizes.find((s) => s.size === size);
  const stock = chosen ? chosen.quantity : null;
  const related = useMemo(() => {
    if (!product) return [];
    const others = products.filter((p) => p.id !== product.id);
    const same = others.filter((p) => categoryOf(p) === categoryOf(product));
    return [...same, ...others.filter((p) => !same.includes(p))].slice(0, 4);
  }, [products, product]);

  if (error && !product) {
    return (
      <div className="l-container l-section">
        <div className="l-empty">
          <strong className="l-h3">We couldn't find that piece</strong>
          <span className="l-small l-muted">It may have sold out. Have a look at what's in stock.</span>
          <Link to="/shop" className="l-btn">Browse the shop</Link>
        </div>
      </div>
    );
  }
  if (loading || !product) return <Loader />;

  function add() {
    if (!chosen) {
      toast('Please choose a size first');
      return;
    }
    dispatch(addToCart({
      id: product.id,
      productName: product.productName,
      price: Number(product.price),
      image: product.mainImage,
      size: chosen.size,
      quantity: qty,
      totalQuantity: chosen.quantity,
      category: product.category,
    }));
    track('AddToCart', { content_ids: [product.id], content_type: 'product', value: product.price * qty, currency: 'ZMW' });
    setAdded(true);
    toast(`${product.productName} added to cart`, { to: '/cart', label: 'View cart' });
  }

  const addLabel = !chosen ? 'Choose a size' : `Add to cart · ${money(product.price * qty)}`;

  return (
    <>
      <div className="l-container l-breadcrumb l-hide-phone">
        <Link to="/">Home</Link> / <Link to={`/shop?category=${encodeURIComponent(categoryOf(product))}`}>{categoryOf(product)}</Link> / <span style={{ color: 'var(--ink)' }}>{product.productName}</span>
      </div>

      <section className="l-container l-section-sm l-has-mobile-bar">
        <div className="l-row l-wrap l-gap-32" style={{ alignItems: 'flex-start', gap: 56 }}>
          <div className="l-gallery" style={{ flex: '1 1 460px', minWidth: 0 }}>
            {images.length > 1 && (
              <div className="l-thumbs">
                {images.map((src, i) => (
                  <button key={src} type="button" className="l-thumb" aria-pressed={image === src} aria-label={`Show photo ${i + 1}`} onClick={() => setImage(src)}>
                    <img src={src} alt="" />
                  </button>
                ))}
              </div>
            )}
            <div className="l-gallery-main"><img src={image || product.mainImage} alt={product.productName} /></div>
          </div>

          <div className="l-stack l-gap-24" style={{ flex: '1 1 400px', minWidth: 0 }}>
            <div className="l-stack l-gap-8">
              <span className="l-eyebrow">{categoryOf(product)}</span>
              <h1 className="l-h1" style={{ fontSize: 'clamp(32px, 4.5vw, 52px)' }}>{product.productName}</h1>
              <span style={{ fontSize: 24, fontWeight: 500 }}>{money(product.price)}</span>
              <span className="l-small" style={{ color: 'var(--green)', fontWeight: 500 }}>
                {stock === null ? 'In stock' : stock > 0 ? `In stock · ${stock} left in size ${size}` : 'Sold out in this size'}
              </span>
            </div>
            {product.description && <p className="l-lead" style={{ fontSize: 16 }}>{product.description}</p>}

            {sizes.length > 0 && (
              <div className="l-stack l-gap-8">
                <span className="l-small" style={{ fontWeight: 500, letterSpacing: '0.06em', textTransform: 'uppercase' }}>Size</span>
                <div className="l-chips">
                  {sizes.map((s) => (
                    <button key={s.size} type="button" className="l-chip" aria-pressed={size === s.size} disabled={s.quantity <= 0}
                      style={s.quantity <= 0 ? { opacity: 0.45, textDecoration: 'line-through' } : undefined}
                      onClick={() => { setSize(s.size); setQty(1); setAdded(false); }}>
                      {s.size}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="l-buybar">
              <div className="l-stepper" aria-label="Quantity">
                <button type="button" aria-label="Decrease quantity" onClick={() => setQty(Math.max(1, qty - 1))}>−</button>
                <span aria-live="polite">{qty}</span>
                <button type="button" aria-label="Increase quantity" onClick={() => setQty(Math.min(stock || 1, qty + 1))} disabled={!chosen || qty >= stock}>+</button>
              </div>
              <button type="button" className="l-btn l-btn-lg l-hide-phone" style={{ flex: '1 1 220px' }} onClick={add}>{addLabel}</button>
            </div>
            {added && <Link to="/cart" className="l-btn l-btn-soft l-btn-lg">View cart &amp; checkout <Icon name="arrow" size={18} /></Link>}
            <WhatsAppButton label="Ask about this on WhatsApp" className="l-btn l-btn-outline l-btn-lg l-hide-phone" text={`Hi Lumina, I'm interested in the ${product.productName} (${money(product.price)}).`} />

            <div className="l-stack" style={{ borderTop: '1px solid var(--line)' }}>
              {['Rings', 'Necklaces', 'Bracelets', 'Earrings', 'Watches'].includes(categoryOf(product)) && (
                <div className="l-info-row"><strong>Material</strong>Stainless or titanium steel. Does not fade, react or tarnish.</div>
              )}
              <div className="l-info-row"><strong>Delivery</strong>Yango biker in Lusaka, Platinum outside Lusaka.</div>
              <div className="l-info-row"><strong>Packing</strong>Necklaces and sets come boxed. Cards and rose boxes on request.</div>
            </div>
          </div>
        </div>
      </section>

      {related.length > 0 && (
        <section className="l-band">
          <div className="l-container l-stack l-gap-24">
            <h2 className="l-h2">You may also like</h2>
            <div className="l-grid">{related.map((p) => <ProductCard key={p.id} product={p} />)}</div>
          </div>
        </section>
      )}

      <div className="l-mobile-bar">
        <a className="l-icon-btn" href={whatsappLink(`Hi Lumina, I'm interested in the ${product.productName}.`)} target="_blank" rel="noreferrer" aria-label="Ask on WhatsApp" style={{ border: '1px solid var(--ink)', width: 50, height: 50, borderRadius: 25 }}>
          <Icon name="whatsapp" />
        </a>
        {added
          ? <Link to="/cart" className="l-btn l-btn-lg" style={{ flex: 1 }}>Added · View cart</Link>
          : <button type="button" className="l-btn l-btn-lg" style={{ flex: 1 }} onClick={add}>{addLabel}</button>}
      </div>
    </>
  );
}
