import { Link, useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { addToCart } from '../../store/cartSlice';
import { categoryOf, money, parseSizes, track } from '../../utils/shop';
import { useToast } from './Toast';

// Quick add works when a product has a single size in stock; otherwise the
// button opens the product page so the shopper can choose a size.
export default function ProductCard({ product, tag }) {
  const to = `/product/${product.id}`;
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const toast = useToast();
  const sizes = parseSizes(product).filter((s) => s.quantity > 0);
  const single = sizes.length === 1 ? sizes[0] : null;

  function quickAdd() {
    if (!single) {
      navigate(to);
      return;
    }
    dispatch(addToCart({
      id: product.id,
      productName: product.productName,
      price: Number(product.price),
      image: product.mainImage,
      size: single.size,
      quantity: 1,
      totalQuantity: single.quantity,
      category: product.category,
    }));
    track('AddToCart', { content_ids: [product.id], content_type: 'product', value: Number(product.price), currency: 'ZMW' });
    toast(`${product.productName} added to cart`, { to: '/cart', label: 'View cart' });
  }

  return (
    <article className="l-card">
      <Link to={to} className="l-card-media" aria-label={product.productName}>
        <img src={product.mainImage} alt={product.productName} loading="lazy" />
        {tag && <span className="l-tag">{tag}</span>}
      </Link>
      <Link to={to} className="l-card-name">{product.productName}</Link>
      <span className="l-card-meta">{categoryOf(product)}</span>
      <div className="l-card-row">
        <span className="l-price">{money(product.price)}</span>
        <button type="button" className="l-btn l-btn-outline l-btn-sm" onClick={quickAdd} aria-label={single ? `Add ${product.productName} to cart` : `Choose a size for ${product.productName}`}>
          {single ? 'Add +' : 'Choose size'}
        </button>
      </div>
    </article>
  );
}

export function CardSkeleton() {
  return (
    <div className="l-card" aria-hidden="true">
      <div className="l-skeleton" style={{ aspectRatio: '1 / 1' }} />
      <div className="l-skeleton" style={{ height: 18, width: '70%', borderRadius: 6 }} />
      <div className="l-skeleton" style={{ height: 14, width: '40%', borderRadius: 6 }} />
    </div>
  );
}
