import { LENCO_PUBLIC_KEY, LENCO_SCRIPT_URL } from '../config';

const API = '/api';

async function post(path, body) {
  const res = await fetch(`${API}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  return { ok: res.ok, status: res.status, data };
}

export function quoteCart(cart) {
  return post('/checkout/quote', { cart: cart.map(({ id, size, quantity }) => ({ id, size, quantity })) });
}

export function createOrder(payload) {
  return post('/orders', payload);
}

let scriptPromise = null;
export function loadLenco() {
  if (window.LencoPay) return Promise.resolve(window.LencoPay);
  if (!scriptPromise) {
    scriptPromise = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = LENCO_SCRIPT_URL;
      s.async = true;
      s.onload = () => (window.LencoPay ? resolve(window.LencoPay) : reject(new Error('Lenco did not load')));
      s.onerror = () => { scriptPromise = null; reject(new Error('Could not reach Lenco')); };
      document.body.appendChild(s);
    });
  }
  return scriptPromise;
}

export function newReference() {
  return `lumina-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

// Opens the Lenco popup. Resolves with { outcome: 'success' | 'pending' | 'closed', reference }.
export async function payWithLenco({ amount, email, name = 'Lumina Customer', phone, method, reference }) {
  const LencoPay = await loadLenco();
  const [firstName, ...rest] = String(name).trim().split(/\s+/);
  return new Promise((resolve) => {
    LencoPay.getPaid({
      key: LENCO_PUBLIC_KEY,
      reference,
      email,
      amount,
      currency: 'ZMW',
      label: 'Lumina order',
      channels: method === 'card' ? ['card'] : ['mobile-money'],
      customer: { firstName, lastName: rest.join(' ') || firstName, phone: String(phone) },
      onSuccess: (response) => resolve({ outcome: 'success', reference: response?.reference || reference }),
      onConfirmationPending: () => resolve({ outcome: 'pending', reference }),
      onClose: () => resolve({ outcome: 'closed', reference }),
    });
  });
}
