import { useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { reduceQuantity, removeFromCart, setNote, setSpecialPacking, updateQuantity } from '../store/cartSlice';
import Icon from '../components/store/Icon';
import { cartWhatsappMessage, logView, money, totals, whatsappLink } from '../utils/shop';
import { DISCOUNT_RATE, DISCOUNT_THRESHOLD } from '../config';

export default function Cart() {
  const dispatch = useDispatch();
  const { cart, note, specialPacking } = useSelector((s) => s.cart);
  const { subtotal, discount, total, items } = totals(cart);

  useEffect(() => { logView('cart', 'cartPage'); }, []);

  if (cart.length === 0) {
    return (
      <div className="l-container l-section">
        <div className="l-empty" style={{ padding: '56px 24px' }}>
          <Icon name="bag" size={36} />
          <strong className="l-h3">Your cart is empty</strong>
          <span className="l-small l-muted">Find something you love, or build a gift.</span>
          <div className="l-row l-wrap l-gap-12" style={{ justifyContent: 'center' }}>
            <Link to="/shop" className="l-btn">Shop all</Link>
            <Link to="/gift-builder" className="l-btn l-btn-outline">Build a gift</Link>
          </div>
        </div>
      </div>
    );
  }

  const extra = [specialPacking ? 'I would like special packing (card / rose box).' : '', note ? `Note: ${note}` : ''].filter(Boolean).join('\n');
  const toDiscount = DISCOUNT_THRESHOLD - subtotal;

  return (
    <div className="l-container l-section l-stack l-gap-24">
      <div className="l-between l-wrap" style={{ alignItems: 'flex-end' }}>
        <h1 className="l-h2">Your cart</h1>
        <Link to="/shop" className="l-link">Continue shopping</Link>
      </div>

      <div className="l-row l-wrap" style={{ alignItems: 'flex-start', gap: 40 }}>
        <div className="l-stack l-gap-16" style={{ flex: '999 1 520px', minWidth: 0 }}>
          {cart.map((line) => (
            <div className="l-cart-line" key={`${line.id}-${line.size}`}>
              <img src={line.image} alt={line.productName} />
              <div className="l-stack l-gap-4" style={{ flex: 1, minWidth: 0 }}>
                <div className="l-between" style={{ alignItems: 'flex-start' }}>
                  <Link to={`/product/${line.id}`} className="l-serif" style={{ fontSize: 22, fontWeight: 600, lineHeight: 1.15 }}>{line.productName}</Link>
                  <button type="button" className="l-icon-btn" style={{ margin: '-8px -8px 0 0', color: 'var(--ink-soft)' }} aria-label={`Remove ${line.productName}`} onClick={() => dispatch(removeFromCart(line))}>
                    <Icon name="trash" size={19} />
                  </button>
                </div>
                <span className="l-small l-muted">Size: {line.size}</span>
                <div className="l-between" style={{ marginTop: 6 }}>
                  <div className="l-stepper l-stepper-sm" aria-label={`Quantity of ${line.productName}`}>
                    <button type="button" aria-label="Decrease quantity" onClick={() => dispatch(reduceQuantity(line))} disabled={line.quantity <= 1}>−</button>
                    <span>{line.quantity}</span>
                    <button type="button" aria-label="Increase quantity" onClick={() => dispatch(updateQuantity(line))} disabled={line.quantity >= line.totalQuantity}>+</button>
                  </div>
                  <span className="l-price" style={{ fontSize: 17 }}>{money(line.price * line.quantity)}</span>
                </div>
                {line.quantity >= line.totalQuantity && <span className="l-xsmall l-muted">That's all we have in this size.</span>}
              </div>
            </div>
          ))}

          <button type="button" role="switch" aria-checked={specialPacking} onClick={() => dispatch(setSpecialPacking(!specialPacking))} className="l-dashed l-row l-gap-16" style={{ textAlign: 'left', width: '100%' }}>
            <Icon name="gift" size={28} stroke={1.4} style={{ color: 'var(--gold-text)', flexShrink: 0 }} />
            <span className="l-stack" style={{ flex: 1 }}>
              <strong style={{ fontWeight: 500 }}>Add special packing</strong>
              <span className="l-small l-muted">A card or rose box. We confirm the extra fee with you on WhatsApp.</span>
            </span>
            <span className="l-switch" />
          </button>

          <label className="l-field">Order note (optional)
            <textarea className="l-input" placeholder="A message for the card, or delivery instructions" value={note} onChange={(e) => dispatch(setNote(e.target.value))} maxLength={500} />
          </label>
        </div>

        <aside className="l-panel l-stack l-gap-12" style={{ flex: '1 1 340px', minWidth: 0 }}>
          <h2 className="l-h3" style={{ fontSize: 30, fontWeight: 500 }}>Order summary</h2>
          <div className="l-line-row"><span>Subtotal ({items} {items === 1 ? 'item' : 'items'})</span><span>{money(subtotal)}</span></div>
          <div className="l-line-row"><span>Discount</span><span>{discount ? `− ${money(discount)}` : '—'}</span></div>
          <div className="l-line-row"><span>Delivery</span><span>Confirmed on WhatsApp</span></div>
          {toDiscount > 0 && (
            <div className="l-soft l-small" style={{ padding: '12px 14px', borderRadius: 14 }}>
              Orders over {money(DISCOUNT_THRESHOLD)} get {Math.round(DISCOUNT_RATE * 100)}% off. You're {money(toDiscount)} away.
            </div>
          )}
          <div className="l-total-row"><span>Total</span><span>{money(total)}</span></div>
          <Link to="/checkout" className="l-btn l-btn-lg l-btn-block">Checkout</Link>
          <a className="l-btn l-btn-outline l-btn-block" href={whatsappLink(cartWhatsappMessage(cart, extra))} target="_blank" rel="noreferrer">
            <Icon name="whatsapp" size={18} />Or send this order on WhatsApp
          </a>
        </aside>
      </div>
    </div>
  );
}
