import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import girl from '../pics/girl.png';
import ProductCard, { CardSkeleton } from '../components/store/ProductCard';
import { FaqList, TrustStrip, WhatsAppButton } from '../components/store/Blocks';
import useProducts from '../utils/useProducts';
import { categoryMark, categoryOf, logView, newestIds, track } from '../utils/shop';
import { CATEGORIES } from '../config';

const HOME_CATEGORIES = ['Rings', 'Necklaces', 'Bracelets', 'Earrings', 'Watches', 'Jewelry Boxes', 'Gift Boxes', 'Jewelry Stands'];

function useIsPhone() {
  const query = '(max-width: 767px)';
  const [phone, setPhone] = useState(() => window.matchMedia(query).matches);
  useEffect(() => {
    const m = window.matchMedia(query);
    const fn = () => setPhone(m.matches);
    m.addEventListener('change', fn);
    return () => m.removeEventListener('change', fn);
  }, []);
  return phone;
}

export default function Home() {
  const { products, loading } = useProducts();
  const [filter, setFilter] = useState('All');
  const isPhone = useIsPhone();

  useEffect(() => {
    logView('home', 'HomePage');
    track('PageView');
  }, []);

  const present = useMemo(() => new Set(products.map(categoryOf)), [products]);
  const filterChips = useMemo(() => ['All', ...CATEGORIES.map((c) => c.name).filter((n) => present.has(n))].slice(0, 5), [present]);

  const shown = useMemo(() => {
    const list = filter === 'All' ? products : products.filter((p) => categoryOf(p) === filter);
    return list.slice(0, isPhone ? 2 : 8);
  }, [products, filter, isPhone]);

  const newest = useMemo(() => newestIds(products), [products]);
  const featured = products.find((p) => /box/i.test(p.productName)) || products[0];

  return (
    <>
      <section className="l-container l-hero">
        <div className="l-hero-text">
          <p className="l-eyebrow">Jewelry &amp; keepsakes</p>
          <h1 className="l-h1">Little luxuries, <br className="l-hide-phone" /><span className="l-italic">beautifully kept.</span></h1>
          <p className="l-lead" style={{ maxWidth: 470 }}>
            Stainless and titanium steel jewelry that does not fade, plus the stands and gift boxes to keep it in. Shop online, or chat with us on WhatsApp and we will help you choose.
          </p>
          <div className="l-row l-wrap l-gap-12" style={{ marginTop: 6 }}>
            <a href="#new" className="l-btn">Shop new arrivals</a>
            <WhatsAppButton label="WhatsApp us" />
          </div>
        </div>
        <div className="l-hero-media">
          <div style={{ position: 'relative', width: '100%', maxWidth: 460 }}>
          <div className="l-hero-arch"><img src={girl} alt="Model wearing Lumina earrings" /></div>
          {featured && (
            <Link to={`/product/${featured.id}`} className="l-float-card">
              <span style={{ fontSize: 11, letterSpacing: '0.14em', textTransform: 'uppercase', color: 'var(--gold-text)' }}>Featured</span>
              <span className="l-serif" style={{ fontSize: 20, fontWeight: 600 }}>{featured.productName}</span>
              <span className="l-small l-muted">ZMW {featured.price}</span>
            </Link>
          )}
          </div>
        </div>
      </section>

      <section className="l-band">
        <div className="l-container l-stack l-gap-24">
          <h2 className="l-h2 l-center" style={{ fontSize: isPhone ? 24 : 40 }}>Shop by category</h2>
          <div className="l-cat-grid">
            {HOME_CATEGORIES.map((name) => (
              <Link key={name} to={`/shop?category=${encodeURIComponent(name)}`} className="l-cat">
                <span className="l-cat-dot">{categoryMark(name)}</span>
                <span>{name}</span>
              </Link>
            ))}
          </div>
        </div>
      </section>

      <section id="new" className="l-container l-section l-stack l-gap-24">
        <div className="l-between l-wrap" style={{ alignItems: 'flex-end' }}>
          <div className="l-stack l-gap-4">
            <p className="l-eyebrow">Just in</p>
            <h2 className="l-h2">New arrivals</h2>
          </div>
          <div className="l-chips" role="tablist" aria-label="Filter new arrivals">
            {filterChips.map((c) => (
              <button key={c} type="button" role="tab" aria-selected={filter === c} className="l-chip" onClick={() => setFilter(c)}>{c}</button>
            ))}
          </div>
        </div>
        <div className="l-grid">
          {loading
            ? Array.from({ length: isPhone ? 2 : 4 }).map((_, i) => <CardSkeleton key={i} />)
            : shown.map((p, i) => <ProductCard key={p.id} product={p} tag={newest.has(p.id) ? 'New' : null} />)}
        </div>
        {!loading && shown.length === 0 && (
          <div className="l-empty">
            <strong className="l-h3">Nothing here yet</strong>
            <span className="l-small l-muted">Ask us on WhatsApp what is in stock right now.</span>
          </div>
        )}
        <Link to={filter === 'All' ? '/shop' : `/shop?category=${encodeURIComponent(filter)}`} className="l-btn l-btn-outline" style={{ alignSelf: 'center' }}>View all products</Link>
      </section>

      <section className="l-container l-section l-hide-phone">
        <div className="l-dark l-split">
          <div className="l-split-text">
            <p className="l-eyebrow" style={{ color: 'var(--gold-light)' }}>Gifting</p>
            <h2 className="l-h2">A gift that says it for you</h2>
            <p className="l-lead" style={{ color: 'var(--line)', maxWidth: 440 }}>Build a gift from jewelry, hair accessories and flowers, then choose a box. Tell us who it is for and we will help you put it together.</p>
            <div className="l-row l-wrap l-gap-12">
              <Link to="/gifting" className="l-btn l-btn-light">Explore gifting</Link>
              <Link to="/gift-builder" className="l-btn l-btn-ghost-light">Build a gift</Link>
            </div>
          </div>
          <div className="l-split-media">{featured && <img src={featured.mainImage} alt={featured.productName} />}</div>
        </div>
      </section>

      <div className="l-hide-phone"><TrustStrip /></div>

      <section className="l-container l-section l-stack l-gap-24 l-hide-phone" style={{ maxWidth: 880 }}>
        <h2 className="l-h2 l-center">Questions, answered</h2>
        <FaqList initialOpen={1} />
        <WhatsAppButton label="Still unsure? Chat with us" className="l-btn" />
      </section>
    </>
  );
}
