import { useEffect, useState } from 'react';
import { Link, NavLink, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import logo from '../pics/logo-wordmark.png';
import Icon from '../components/store/Icon';
import { ToastProvider } from '../components/store/Toast';
import { CATEGORIES } from '../config';
import { whatsappLink } from '../utils/shop';

const NAV_CATEGORIES = ['Rings', 'Necklaces', 'Bracelets', 'Earrings', 'Watches'];

function Header({ cartCount }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [q, setQ] = useState('');

  function submit(e) {
    e.preventDefault();
    navigate(`/shop${q.trim() ? `?q=${encodeURIComponent(q.trim())}` : ''}`);
  }

  const params = new URLSearchParams(location.search);
  const activeCat = location.pathname === '/shop' ? params.get('category') : null;

  return (
    <header className="l-header">
      <div className="l-container l-header-inner">
        <Link to="/" className="l-logo" aria-label="Lumina home">
          <img src={logo} alt="Lumina" />
        </Link>
        <nav className="l-nav" aria-label="Main">
          <Link to="/shop" aria-current={location.pathname === '/shop' && !activeCat ? 'page' : undefined}>Shop all</Link>
          {NAV_CATEGORIES.map((c) => (
            <Link key={c} to={`/shop?category=${encodeURIComponent(c)}`} aria-current={activeCat === c ? 'page' : undefined}>{c}</Link>
          ))}
          <NavLink to="/gifting" aria-current={location.pathname.startsWith('/gift') ? 'page' : undefined}>Gifting</NavLink>
          <NavLink to="/faq">FAQ</NavLink>
        </nav>
        <div className="l-header-actions">
          <form className="l-search" role="search" onSubmit={submit}>
            <label className="l-sr" htmlFor="site-search">Search</label>
            <input id="site-search" placeholder="Search jewelry…" value={q} onChange={(e) => setQ(e.target.value)} />
            <button className="l-icon-btn" type="submit" aria-label="Search"><Icon name="search" size={20} /></button>
          </form>
          <Link to="/shop?search=1" className="l-icon-btn l-phone-only" aria-label="Search"><Icon name="search" size={21} /></Link>
          <Link to="/cart" className="l-icon-btn" aria-label={`Cart, ${cartCount} items`}>
            <Icon name="bag" />
            {cartCount > 0 && <span className="l-badge">{cartCount}</span>}
          </Link>
        </div>
      </div>
    </header>
  );
}

function Footer() {
  return (
    <footer className="l-footer">
      <div className="l-container l-footer-top">
        <div className="l-stack l-gap-12" style={{ flex: '1 1 280px' }}>
          <img src={logo} alt="Lumina" />
          <span style={{ maxWidth: 320, fontSize: 15 }}>Stainless and titanium steel jewelry that does not fade. Based in Kabwata, Lusaka.</span>
        </div>
        <div className="l-stack l-gap-12" style={{ fontSize: 15 }}>
          <strong style={{ color: 'var(--cream)', fontWeight: 500 }}>Shop</strong>
          {CATEGORIES.slice(0, 5).map((c) => (
            <Link key={c.name} to={`/shop?category=${encodeURIComponent(c.name)}`}>{c.name}</Link>
          ))}
        </div>
        <div className="l-stack l-gap-12" style={{ fontSize: 15 }}>
          <strong style={{ color: 'var(--cream)', fontWeight: 500 }}>Help</strong>
          <Link to="/gifting">Gifting</Link>
          <Link to="/faq">FAQ</Link>
          <a href={whatsappLink()} target="_blank" rel="noreferrer">WhatsApp us</a>
        </div>
      </div>
      <div className="l-container l-footer-bottom">© {new Date().getFullYear()} Lumina</div>
    </footer>
  );
}

function BottomTabs({ cartCount }) {
  const { pathname } = useLocation();
  const is = (p) => (p === '/' ? pathname === '/' : pathname.startsWith(p));
  return (
    <nav className="l-tabs" aria-label="Bottom">
      <Link to="/" aria-current={is('/') ? 'page' : undefined}><Icon name="home" />Home</Link>
      <Link to="/gifting" aria-current={is('/gift') ? 'page' : undefined}><Icon name="gift" />Gifts</Link>
      <Link to="/faq" aria-current={is('/faq') ? 'page' : undefined}><Icon name="help" />Help</Link>
      <a href={whatsappLink()} target="_blank" rel="noreferrer"><Icon name="whatsapp" />WhatsApp</a>
      <Link to="/cart" aria-current={is('/cart') ? 'page' : undefined}>
        <Icon name="bag" />Cart
        {cartCount > 0 && <span className="l-badge">{cartCount}</span>}
      </Link>
    </nav>
  );
}

export default function StoreLayout() {
  const { cart } = useSelector((s) => s.cart);
  const cartCount = cart.reduce((n, i) => n + i.quantity, 0);
  const { pathname } = useLocation();

  useEffect(() => { window.scrollTo(0, 0); }, [pathname]);

  return (
    <ToastProvider>
      <div className="l-app">
        <div className="l-announce">Order online or on WhatsApp · Delivery in Lusaka by Yango, outside Lusaka by Platinum</div>
        <Header cartCount={cartCount} />
        <main className="l-main"><Outlet /></main>
        <Footer />
        <BottomTabs cartCount={cartCount} />
      </div>
    </ToastProvider>
  );
}
